    m.def("conv2d_multiply_leakyrelu_gelu_cuda", &conv2d_multiply_leakyrelu_gelu_cuda, "Fused multiply+leakyrelu+gelu CUDA");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
