#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

__global__ void fused_multiply_leakyrelu_gelu_kernel(
    const float* __restrict__ x_in,
    float* __restrict__ x_out,
    const float* __restrict__ multiplier,
    int total,
    int HW,
    int C
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total) return;

    int c = (idx / HW) % C;
    float v = x_in[idx] * __ldg(&multiplier[c]);

    // Branchless LeakyReLU with slope 0.01
    v = fmaxf(v, 0.01f * v);

    // Tanh-approx GELU: 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
    float v3 = v * v * v;
    float inner = 0.7978845608f * __fmaf_rn(0.044715f, v3, v);
    v = 0.5f * v * (1.0f + tanhf(inner));

    x_out[idx] = v;
