    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(multiplier.is_cuda(), "multiplier must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    auto mult_flat = multiplier.contiguous().flatten();
    int C = (int)mult_flat.numel();

    int N = (int)x.size(0);
    int Cx = (int)x.size(1);
    int H = (int)x.size(2);
    int W = (int)x.size(3);
    int HW = H * W;
    int total = N * Cx * HW;

    TORCH_CHECK(Cx == C, "multiplier channel count must match x channel count");

    auto out = torch::empty_like(x);

    int block = 256;
    int grid = (total + block - 1) / block;

    fused_multiply_leakyrelu_gelu_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        mult_flat.data_ptr<float>(),
        total,
        HW,
        C
    );

    return out;
